import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Box, Button, Paper } from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import dayjs from 'dayjs';
import 'dayjs/locale/de';
import { useApp } from '../../contexts/AppContext';
import { WorkAppointment } from '../../types/models';
import { writeActivityLog } from '../../domain/activityLog';
import { AppointmentDialog } from './AppointmentDialog';
import { useConfirm } from '../common/ConfirmProvider';
import { AppointmentDetailsDialog } from './AppointmentDetailsDialog';
import { getDefaultNewSlot, useIsMobile } from '../../hooks/useIsMobile';
import { CALENDAR_MESSAGES, CalendarViewOption, getCalendarStyle } from '../Calendar/calendarMessages';
import { Calendar, dayjsLocalizer } from 'react-big-calendar';

const localizer = dayjsLocalizer(dayjs);

dayjs.locale('de');

export const WorkCalendar: React.FC<{ listView?: boolean }> = ({ listView = false }) => {
  const isMobile = useIsMobile();
  // v2: Listenansicht verfügbar und auf Smartphones Standard
  const preferList = listView && isMobile;
  const [appointments, setAppointments] = useState<WorkAppointment[]>([]);
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [detailsDialogOpen, setDetailsDialogOpen] = useState(false);
  const [selectedAppointment, setSelectedAppointment] = useState<WorkAppointment | undefined>();
  const [displayDate, setDisplayDate] = useState<Date>(new Date());
  const [selectedSlot, setSelectedSlot] = useState<{ start: Date; end: Date } | null>(null);
  const { database, currentUser, isAdmin, isAnyBootswart, systemConfig } = useApp();
  const confirm = useConfirm();

  const defaultView: CalendarViewOption = preferList ? 'agenda' :
    currentUser?.preferences?.calendarDefaults?.arbeitskalender ??
    systemConfig.calendarDefaults?.arbeitskalender ??
    'week';
  const [selectedView, setSelectedView] = useState<CalendarViewOption>(defaultView);
  const calendarStyle = getCalendarStyle(listView, isMobile, selectedView);

  useEffect(() => {
    setSelectedView(preferList ? 'agenda' :
      currentUser?.preferences?.calendarDefaults?.arbeitskalender ??
      systemConfig.calendarDefaults?.arbeitskalender ??
      'week'
    );
  }, [preferList, currentUser?.preferences?.calendarDefaults?.arbeitskalender, systemConfig.calendarDefaults?.arbeitskalender]);

  const refreshAppointments = useCallback(async () => {
    const aptms = await database.getDocuments<WorkAppointment>('workAppointments');
    setAppointments(aptms.filter(a => !a.private || (a.participants.some(p => p.userId === currentUser?.id))));
    if (selectedAppointment) {
      setSelectedAppointment(aptms.find(a => a.id === selectedAppointment.id));
    }
  }, [database, currentUser, selectedAppointment]);

  useEffect(() => {
    refreshAppointments();
  }, [refreshAppointments]);


  const handleOpenCreateDialog = ({ start, end }: { start: Date; end: Date }) => {
    setSelectedSlot({ start, end });
    setSelectedAppointment(undefined);
    setCreateDialogOpen(true);
  };

  const handleOpenDetailsDialog = (appointment: WorkAppointment) => {
    setSelectedAppointment(appointment);
    setDetailsDialogOpen(true);
  };

  const { startTime, endTime } = useMemo(() => {
    // if start is not 00:00 and end is not 00:00 use start and end times
    if (selectedSlot && selectedSlot.start && selectedSlot.end && (selectedSlot.start.getHours() !== 0 || selectedSlot.end.getHours() !== 0)) {
      return { startTime: selectedSlot.start, endTime: selectedSlot.end };
    }
    let start = selectedSlot?.start || new Date();
    start.setHours(10, 0, 0, 0);
    let end = selectedSlot?.end || new Date();
    // minus one day because endTime is next day 00:00 by default
    end.setDate(end.getDate() - 1);
    end.setHours(16, 0, 0, 0);
    return { startTime: start, endTime: end };
  }, [selectedSlot]);

  return (
    <>
      <Paper sx={{ p: { xs: 1, sm: 2 } }}>
        {(isAdmin || isAnyBootswart) && (
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 1 }}>
            {/* Neuer Termin ohne Slot-Auswahl – auf Touch-Geräten sonst nur per langem Druck erreichbar. */}
            <Button size="small" variant="contained" startIcon={<AddIcon />} onClick={() => handleOpenCreateDialog(getDefaultNewSlot())}>
              Termin anlegen
            </Button>
          </Box>
        )}
        <Calendar
          date={displayDate}
          localizer={localizer}
          events={appointments}
          startAccessor="startTime"
          endAccessor="endTime"
          style={calendarStyle}
          longPressThreshold={100}
          scrollToTime={new Date(1970, 0, 1, 7, 0, 0)}
          selectable={isAdmin || isAnyBootswart}
          onSelectSlot={handleOpenCreateDialog}
          onSelectEvent={handleOpenDetailsDialog}
          view={selectedView}
          views={listView ? ['agenda', 'month', 'week', 'day'] : ['month', 'week', 'day']}
          eventPropGetter={(event: WorkAppointment) => ({
            className: event.private ? 'private-appointment' : undefined,
            style: {
              backgroundColor: event.private ? '#f3e5f5' : '#1976d2',
              color: event.private ? '#9c27b0' : '#fff',
              border: event.private ? '1px solid #9c27b0' : '1px solid #1565c0',
              fontWeight: event.private ? 500 : 400
            }
          })}
          onNavigate={(range) => {
            setDisplayDate(range);
          }}
          onView={(v) => setSelectedView(v as CalendarViewOption)}
          titleAccessor="title"
          messages={CALENDAR_MESSAGES}
          dayLayoutAlgorithm="no-overlap"
        />
    </Paper>

      {createDialogOpen && (
        <AppointmentDialog
          open={createDialogOpen}
          onClose={() => setCreateDialogOpen(false)}
          onSave={async (appointment) => {
            const newId = await database.addDocument('workAppointments', {
              ...appointment,
              createdAt: new Date(),
              updatedAt: new Date(),
            });
            if (currentUser) {
              await writeActivityLog(database, {
                type: 'workHour.created',
                entityId: newId,
                entityType: 'workHour',
                actorId: currentUser.id,
                actorName: currentUser.displayName,
                details: { title: appointment.title ?? '' },
              });
            }
            setCreateDialogOpen(false);
            await refreshAppointments();
          }}
          startTime={startTime}
          endTime={endTime}
        />
      )}

      {detailsDialogOpen && selectedAppointment && (
        <AppointmentDetailsDialog
          open={detailsDialogOpen}
          onClose={() => setDetailsDialogOpen(false)}
          appointment={selectedAppointment}
          onUpdate={async () => {
            await refreshAppointments();
          }}
          onDelete={async () => {
            const confirmed = await confirm({
              title: 'Termin löschen?',
              message: `„${selectedAppointment.title}“ wird mit allen Teilnehmern und Stunden endgültig gelöscht.`,
              confirmLabel: 'Löschen',
              destructive: true,
            });
            if (!confirmed) return;
            await database.deleteDocument('workAppointments', selectedAppointment.id);
            if (currentUser) {
              await writeActivityLog(database, {
                type: 'workHour.deleted',
                entityId: selectedAppointment.id,
                entityType: 'workHour',
                actorId: currentUser.id,
                actorName: currentUser.displayName,
                details: { title: selectedAppointment.title },
              });
            }
            setDetailsDialogOpen(false);
            await refreshAppointments();
          }}
          onCopy={async (copies) => {
            await Promise.all(copies.map(async (copy) => {
              const newId = await database.addDocument('workAppointments', copy);
              if (currentUser) {
                await writeActivityLog(database, {
                  type: 'workHour.created',
                  entityId: newId,
                  entityType: 'workHour',
                  actorId: currentUser.id,
                  actorName: currentUser.displayName,
                  details: { title: copy.title, seriesCopy: true },
                });
              }
            }));
            await refreshAppointments();
          }}
        />
      )}
    </>
  );
};
