import React, { useState, useEffect, useCallback } from 'react';
import {
  Dialog,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  Box,
  Chip,
  TextField,
  Alert,
  FormControlLabel,
  Switch,
} from '@mui/material';
import {
  Check as CheckIcon,
  Close as CloseIcon,
  ContentCopy as CopyIcon,
  Delete as DeleteIcon,
  Edit as EditIcon,
  Save as SaveIcon,
} from '@mui/icons-material';
import dayjs from 'dayjs';
import 'dayjs/locale/de';
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker';
import { useApp } from '../../contexts/AppContext';
import { setReservationStatus } from '../../domain/reservationActions';
import { BoatReservation, Boat } from '../../types/models';
import { useOverlappingReservations } from '../../hooks/useOverlappingReservations';
import { useSnackbar } from 'notistack';
import { syncPublicReservationFeed, deletePublicReservationFeed } from '../../domain/reservationSync';
import { writeActivityLog } from '../../domain/activityLog';
import { CopyReservationSeriesDialog } from './CopyReservationSeriesDialog';
import { useMemberReservationEligibility } from '../../hooks/memberHooks';
import { useResponsiveDialogProps } from '../../hooks/useIsMobile';

dayjs.locale('de');

interface ReservationDetailsDialogProps {
  open: boolean;
  onClose: () => void;
  reservation: BoatReservation;
  onUpdate: () => void;
  onCopy?: (copies: Omit<BoatReservation, 'id'>[]) => Promise<void>;
}

interface EditableReservation {
  title: string;
  description: string;
  startTime: dayjs.Dayjs;
  endTime: dayjs.Dayjs;
  visibility: 'private' | 'public';
  freeSeatsText: string;
}

export const ReservationDetailsDialog: React.FC<ReservationDetailsDialogProps> = ({
  open,
  onClose,
  reservation,
  onUpdate,
  onCopy,
}) => {
  const dialogProps = useResponsiveDialogProps();
  const { database, currentUser, isAdmin, isSuperAdmin } = useApp();
  const { canReserve } = useMemberReservationEligibility();
  const [boat, setBoat] = useState<Boat | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isCopyDialogOpen, setIsCopyDialogOpen] = useState(false);
  const [editedData, setEditedData] = useState<EditableReservation>(() => ({
    title: reservation.title,
    description: reservation.description || '',
    startTime: dayjs(reservation.startTime),
    endTime: dayjs(reservation.endTime),
    visibility: reservation.visibility,
    freeSeatsText: reservation.publicDetails?.freeSeatsText || '',
  }));

  useEffect(() => {
    setEditedData({
      title: reservation.title,
      description: reservation.description || '',
      startTime: dayjs(reservation.startTime),
      endTime: dayjs(reservation.endTime),
      visibility: reservation.visibility,
      freeSeatsText: reservation.publicDetails?.freeSeatsText || '',
    });
  }, [reservation]);


  const fetchBoat = useCallback(async (boatId: string) => {
    try {
      const boatDoc = await database.getDocument<Boat>('boats', boatId);
      if (boatDoc) {
        setBoat(boatDoc);
      }
    } catch (error) {
      console.error('Error fetching boat:', error);
    }
  }, [database]);

  useEffect(() => {
    fetchBoat(reservation.boatId);
  }, [reservation.boatId, fetchBoat]);

  const handleCancel = async () => {
    if (!currentUser || isSubmitting) return;

    setIsSubmitting(true);
    try {
      await database.updateDocument('boatReservations', reservation.id, {
        status: 'cancelled',
        updatedAt: new Date(),
      });
      await deletePublicReservationFeed(database, reservation.id);
      await writeActivityLog(database, {
        type: 'reservation.status_changed',
        entityId: reservation.id,
        entityType: 'reservation',
        actorId: currentUser.id,
        actorName: currentUser.displayName,
        details: { title: reservation.title, previousStatus: reservation.status, newStatus: 'cancelled' },
      });
      onUpdate();
      onClose();
    } catch (error) {
      console.error('Error canceling reservation:', error);
      enqueueSnackbar('Fehler beim Stornieren der Reservierung', { variant: 'error' });
    } finally {
      setIsSubmitting(false);
    }
  };

  const isOwner = currentUser?.id === reservation.userId;
  const isBootswartOrAdmin = (boat && currentUser && (boat.bootswart === currentUser.id || boat.bootswart2 === currentUser.id)) || isAdmin;
  const isFutureReservation = reservation.startTime > new Date();
  const canEdit = (isOwner && reservation.status === 'draft') || (isSuperAdmin && isFutureReservation && !['cancelled', 'rejected'].includes(reservation.status));

  const handleStatusChange = async (newStatus: 'approved' | 'rejected' | 'cancelled') => {
    if (!isBootswartOrAdmin || isSubmitting || !currentUser) return;

    setIsSubmitting(true);
    try {
      await setReservationStatus(database, reservation, newStatus, currentUser, boat ? [boat] : []);
      onUpdate();
      onClose();
    } catch (error) {
      console.error('Error updating reservation status:', error);
      enqueueSnackbar('Fehler beim Aktualisieren des Status', { variant: 'error' });
    } finally {
      setIsSubmitting(false);
    }
  };

  const { hasOverlappingReservations } = useOverlappingReservations({
    startTime: editedData.startTime,
    endTime: editedData.endTime,
    excludeReservationId: reservation.id,
  });

  const { enqueueSnackbar } = useSnackbar();

  const handleSaveChanges = async () => {
    if (isSubmitting) return;

    // Check times
    if (editedData.startTime.isAfter(editedData.endTime)) {
      enqueueSnackbar('Die Endzeit muss später als die Startzeit sein.', { variant: 'error' });
      return;
    }

    setIsSubmitting(true);
    try {
      // Check for overlapping reservations before saving
      const [hasOverlapping] = await hasOverlappingReservations(boat?.id);
      if (hasOverlapping) {
        enqueueSnackbar('Es gibt bereits eine Reservierung in diesem Zeitraum.', { variant: 'error' });
        setIsSubmitting(false);
        return;
      }

      const resolvedPublicDetails = editedData.visibility === 'public'
        ? { freeSeatsText: editedData.freeSeatsText }
        : undefined;

      await database.updateDocument('boatReservations', reservation.id, {
        title: editedData.title,
        description: editedData.description,
        startTime: editedData.startTime.toDate(),
        endTime: editedData.endTime.toDate(),
        visibility: editedData.visibility,
        publicDetails: resolvedPublicDetails ?? null,
        updatedAt: new Date(),
      });
      await syncPublicReservationFeed(database, {
        ...reservation,
        title: editedData.title,
        description: editedData.description,
        startTime: editedData.startTime.toDate(),
        endTime: editedData.endTime.toDate(),
        visibility: editedData.visibility,
        publicDetails: resolvedPublicDetails,
        updatedAt: new Date(),
      }, boat ? [boat] : []);
      if (currentUser) {
        await writeActivityLog(database, {
          type: 'reservation.status_changed',
          entityId: reservation.id,
          entityType: 'reservation',
          actorId: currentUser.id,
          actorName: currentUser.displayName,
          details: { title: editedData.title, action: 'updated' },
        });
      }
      onUpdate();
      setIsEditing(false);
      enqueueSnackbar('Reservierung wurde aktualisiert', { variant: 'success' });
    } catch (error) {
      console.error('Error updating reservation:', error);
      enqueueSnackbar('Fehler beim Aktualisieren der Reservierung', { variant: 'error' });
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleFinalizeDraft = async () => {
    if (!canReserve) {
      enqueueSnackbar('Die Vormerkung kann erst finalisiert werden, wenn die Voraussetzungen erfüllt sind.', { variant: 'warning' });
      return;
    }
    if (isSubmitting) return;

    const isOwnBoatBootswart = !!currentUser && (currentUser.id === boat?.bootswart || currentUser.id === boat?.bootswart2);
    const nextStatus = boat?.requiresApproval && !isOwnBoatBootswart ? 'pending' : 'approved';

    setIsSubmitting(true);
    try {
      await database.updateDocument('boatReservations', reservation.id, {
        status: nextStatus,
        updatedAt: new Date(),
      });
      await syncPublicReservationFeed(database, {
        ...reservation,
        status: nextStatus,
        updatedAt: new Date(),
      }, boat ? [boat] : []);
      if (currentUser) {
        await writeActivityLog(database, {
          type: 'reservation.status_changed',
          entityId: reservation.id,
          entityType: 'reservation',
          actorId: currentUser.id,
          actorName: currentUser.displayName,
          details: { title: reservation.title, previousStatus: 'draft', newStatus: nextStatus },
        });
      }
      enqueueSnackbar('Vormerkung wurde finalisiert.', { variant: 'success' });
      onUpdate();
    } catch (error) {
      console.error('Error finalizing reservation draft:', error);
      enqueueSnackbar('Fehler beim Finalisieren der Vormerkung', { variant: 'error' });
    } finally {
      setIsSubmitting(false);
    }
  };

  const getStatusChip = () => {
    const statusConfig = {
      draft: { label: 'Vormerkung', color: 'warning' as const },
      pending: { label: 'Nicht genehmigt', color: 'info' as const },
      approved: { label: 'Genehmigt', color: 'success' as const },
      rejected: { label: 'Abgelehnt', color: 'error' as const },
      cancelled: { label: 'Storniert', color: 'default' as const },
    } as const;
    const config = statusConfig[reservation.status as keyof typeof statusConfig];
    return (
      <Chip
        size="small"
        label={config.label}
        color={config.color}
      />
    );
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth {...dialogProps}>
      <Box sx={{ bgcolor: 'primary.main', color: 'primary.contrastText', py: 3, px: 3 }}>
        {isEditing ? (
          <TextField
            fullWidth
            value={editedData.title}
            onChange={(e) => setEditedData({ ...editedData, title: e.target.value })}
            variant="standard"
            sx={{
              mb: 1,
              '& .MuiInputBase-input': {
                color: 'primary.contrastText',
                fontSize: '1.5rem',
                fontWeight: 'bold',
              },
              '& .MuiInput-underline:before': {
                borderBottomColor: 'rgba(255, 255, 255, 0.7)',
              },
              '& .MuiInput-underline:hover:not(.Mui-disabled):before': {
                borderBottomColor: 'primary.contrastText',
              },
              '& .MuiInput-underline:after': {
                borderBottomColor: 'primary.contrastText',
              },
            }}
          />
        ) : (
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 1 }} color="primary.contrastText">
            {reservation.title}
          </Typography>
        )}
        {boat && (
          <Typography variant="h6" sx={{ opacity: 0.9, fontWeight: 'normal' }} color="primary.contrastText">
            {boat.name}
          </Typography>
        )}
        <Typography variant="body2" sx={{ opacity: 0.75, mt: 0.5 }} color="primary.contrastText">
          Erstellt von {reservation.userName} · {dayjs(reservation.createdAt).format('DD.MM.YYYY')}
        </Typography>
      </Box>

      <DialogContent sx={{ p: 0 }}>
        <Box sx={{ 
          bgcolor: 'grey.50', 
          p: 3, 
          borderRadius: 1,
        }}>
          {reservation.status === 'draft' && (
            <Alert severity="info" sx={{ mb: 2 }}>
              Diese Reservierung ist aktuell nur eine unverbindliche Vormerkung. Andere Mitglieder werden gewarnt, aber nicht hart blockiert.
            </Alert>
          )}
          {!isEditing ? (reservation.startTime.getDay() === reservation.endTime.getDay()) ? (
            <Box sx={{ display: 'flex', flexDirection: 'column', mb: 2 }}>
              <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
                {dayjs(reservation.startTime).format('DD. MMMM YYYY')}
              </Typography>
              <Typography variant="subtitle1">
                {dayjs(reservation.startTime).format('HH:mm')} - {dayjs(reservation.endTime).format('HH:mm')} Uhr
              </Typography>
            </Box>
          ) : (
            <Box sx={{ display: 'flex', flexDirection: 'row', mb: 2, }}>
              <Box sx={{ display: 'flex', flexDirection: 'column', justifyContent: 'space-between', alignItems: 'center' }}>
                <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
                  {dayjs(reservation.startTime).format('DD. MMMM YYYY')}
                </Typography>
                <Typography variant="subtitle1">
                  {dayjs(reservation.startTime).format('HH:mm')} Uhr
                </Typography>
              </Box>
              <Typography variant="h6" sx={{ fontWeight: 'bold', mx: 3 }}>
                bis
              </Typography>
              <Box sx={{ display: 'flex', flexDirection: 'column', justifyContent: 'space-between', alignItems: 'center' }}>
                <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
                  {dayjs(reservation.endTime).format('DD. MMMM YYYY')}
                </Typography>
                <Typography variant="subtitle1">
                  {dayjs(reservation.endTime).format('HH:mm')} Uhr
                </Typography>
              </Box>
            </Box>
          ) : null}
          
          {isEditing && (
            <Box sx={{ mb: 2, display: 'flex', gap: 2 }}>
              <DateTimePicker
                label="Start Zeit"
                value={editedData.startTime}
                onChange={(newValue) => newValue && setEditedData({ ...editedData, startTime: newValue })}
                sx={{ flex: 1 }}
                format="DD.MM.YYYY HH:mm"
              />
              <DateTimePicker
                label="End Zeit"
                value={editedData.endTime}
                onChange={(newValue) => newValue && setEditedData({ ...editedData, endTime: newValue })}
                sx={{ flex: 1 }}
                format="DD.MM.YYYY HH:mm"
              />
            </Box>
          )}

          {isEditing ? (
            <>
              <TextField
                fullWidth
                multiline
                rows={4}
                value={editedData.description}
                onChange={(e) => setEditedData({ ...editedData, description: e.target.value })}
                sx={{ mb: 3 }}
              />
              <FormControlLabel
                control={
                  <Switch
                    checked={editedData.visibility === 'public'}
                    onChange={(event) => setEditedData({
                      ...editedData,
                      visibility: event.target.checked ? 'public' : 'private',
                    })}
                  />
                }
                label="Öffentlich anzeigen, dass noch Plätze frei sind"
                sx={{ mb: 2 }}
              />
              {editedData.visibility === 'public' && (
                <TextField
                  fullWidth
                  label="Hinweis für Mitfahrende"
                  value={editedData.freeSeatsText}
                  onChange={(e) => setEditedData({ ...editedData, freeSeatsText: e.target.value })}
                  sx={{ mb: 3 }}
                />
              )}
            </>
          ) : (
            <Typography variant="body1" sx={{ mb: 3, whiteSpace: 'pre-line' }}>
              {reservation.description}
            </Typography>
          )}

          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <Typography variant="subtitle2" sx={{ fontWeight: 'bold' }}>
                Status:
              </Typography>
              {getStatusChip()}
            </Box>
            <Typography variant="subtitle2">
              <strong>Reserviert von:</strong> {reservation.userName}
            </Typography>
            {reservation.visibility === 'public' && (
              <Typography variant="subtitle2">
                <strong>Öffentlich sichtbar:</strong> {reservation.publicDetails?.freeSeatsText || 'Mitfahrplätze verfügbar'}
              </Typography>
            )}
          </Box>
        </Box>
      </DialogContent>

      <DialogActions sx={{ px: { xs: 2, sm: 3 }, py: 2, bgcolor: 'grey.50' }}>
        <Box sx={{ display: 'flex', gap: { xs: 1, sm: 2 }, width: '100%', justifyContent: 'space-between', flexWrap: 'wrap' }}>
          <Box sx={{ display: 'flex', gap: { xs: 1, sm: 2 }, flexWrap: 'wrap' }}>
            {(isOwner || isBootswartOrAdmin) && !['cancelled', 'rejected'].includes(reservation.status) && (
              <Button
                color="error"
                variant="outlined"
                onClick={handleCancel}
                disabled={isSubmitting}
                startIcon={<DeleteIcon />}
              >
                Stornieren
              </Button>
            )}
            {onCopy && !isEditing && !['cancelled', 'rejected'].includes(reservation.status) && (isOwner || isBootswartOrAdmin) && (
              <Button
                color="secondary"
                variant="outlined"
                onClick={() => setIsCopyDialogOpen(true)}
                disabled={isSubmitting}
                startIcon={<CopyIcon />}
              >
                Serie
              </Button>
            )}
          </Box>
          <Box sx={{ display: 'flex', gap: { xs: 1, sm: 2 }, flexWrap: 'wrap', justifyContent: 'flex-end', ml: 'auto' }}>
            <Box sx={{ display: 'flex', gap: { xs: 1, sm: 2 }, flexWrap: 'wrap' }}>
              {canEdit && !isEditing && (
                <Button
                  color="primary"
                  variant="outlined"
                  onClick={() => setIsEditing(true)}
                  startIcon={<EditIcon />}
                >
                  Bearbeiten
                </Button>
              )}
              {isEditing && (
                <>
                  <Button
                    onClick={() => setIsEditing(false)}
                    variant="outlined"
                    disabled={isSubmitting}
                    startIcon={<CloseIcon />}
                  >
                    Abbrechen
                  </Button>
                  <Button
                    onClick={handleSaveChanges}
                    variant="contained"
                    disabled={isSubmitting}
                    startIcon={<SaveIcon />}
                  >
                    Speichern
                  </Button>
                </>
              )}
              {!isEditing && (
                <Button onClick={onClose} variant="outlined">
                  Schließen
                </Button>
              )}
            </Box>
            {!isEditing && isBootswartOrAdmin && reservation.status === 'pending' && (
              <Box sx={{ display: 'flex', gap: { xs: 1, sm: 2 }, flexWrap: 'wrap' }}>
                <Button
                  onClick={() => handleStatusChange('rejected')}
                  color="warning"
                  variant="outlined"
                  disabled={isSubmitting}
                  startIcon={<CloseIcon />}
                >
                  Ablehnen
                </Button>
                <Button
                  onClick={() => handleStatusChange('approved')}
                  color="success"
                  variant="contained"
                  disabled={isSubmitting}
                  startIcon={<CheckIcon />}
                >
                  Genehmigen
                </Button>
              </Box>
            )}
            {!isEditing && isOwner && reservation.status === 'draft' && (
              <Button
                onClick={handleFinalizeDraft}
                color="success"
                variant="contained"
                disabled={isSubmitting}
                startIcon={<CheckIcon />}
              >
                Finalisieren
              </Button>
            )}
          </Box>
        </Box>
      </DialogActions>
      {isCopyDialogOpen && onCopy && (
        <CopyReservationSeriesDialog
          open={isCopyDialogOpen}
          onClose={() => setIsCopyDialogOpen(false)}
          reservation={reservation}
          onSave={async (copies) => {
            await onCopy(copies);
            setIsCopyDialogOpen(false);
          }}
        />
      )}
    </Dialog>
  );
};
