import React, { useCallback, useState, useEffect } from 'react';
import { Alert, AlertTitle } from '@mui/material';
import { useMemberReservationEligibility } from '../../hooks/memberHooks';
import {
  Paper,
  Box,
  Chip,
  Tooltip,
  Button,
} from '@mui/material';
import { Calendar, dayjsLocalizer } from 'react-big-calendar';
import dayjs from 'dayjs'
import 'react-big-calendar/lib/css/react-big-calendar.css';
import { useApp } from '../../contexts/AppContext';
import { BoatReservation } from '../../types/models';
import { syncPublicReservationFeed } from '../../domain/reservationSync';
import { writeActivityLog } from '../../domain/activityLog';
import { getContrastColor } from '../../utils/colors';
import { ReservationDialog } from './ReservationDialog';
import { ReservationDetailsDialog } from './ReservationDetailsDialog';
import BlockIcon from '@mui/icons-material/Block';
import AddIcon from '@mui/icons-material/Add';
import { getDefaultNewSlot, useIsMobile } from '../../hooks/useIsMobile';
import { CALENDAR_MESSAGES, CalendarViewOption, getCalendarStyle } from '../Calendar/calendarMessages';

const localizer = dayjsLocalizer(dayjs);

export const BoatReservationCalendar: React.FC<{ listView?: boolean }> = ({ listView = false }) => {
  const isMobile = useIsMobile();
  // v2: Listenansicht verfügbar und auf Smartphones Standard
  const preferList = listView && isMobile;
  const { database, currentUser, boats, systemConfig, isAdmin, isSuperAdmin, reloadCurrentUser } = useApp();
  const { canReserve, missingRequirements } = useMemberReservationEligibility();
  const [allReservations, setAllReservations] = useState<BoatReservation[]>([]);
  const [selectedReservation, setSelectedReservation] = useState<BoatReservation | null>(null);
  const [isDetailsDialogOpen, setIsDetailsDialogOpen] = useState(false);
  const [isReservationDialogOpen, setIsReservationDialogOpen] = useState(false);
  const [displayDate, setDisplayDate] = useState<Date>(new Date());
  const [selectedSlot, setSelectedSlot] = useState<{ start: Date; end: Date } | null>(null);
  const [togglingCancelled, setTogglingCancelled] = useState(false);

  const isAdminOrSuperAdmin = isAdmin || isSuperAdmin;
  const showCancelled = Boolean(isAdminOrSuperAdmin && currentUser?.preferences?.showCancelledReservations);

  const reservations = showCancelled
    ? allReservations
    : allReservations.filter((r) => r.status !== 'cancelled');

  const defaultView: CalendarViewOption = preferList ? 'agenda' :
    currentUser?.preferences?.calendarDefaults?.vormerkbuch ??
    systemConfig.calendarDefaults?.vormerkbuch ??
    'week';
  const [selectedView, setSelectedView] = useState<CalendarViewOption>(defaultView);
  const calendarStyle = getCalendarStyle(listView, isMobile, selectedView);

  useEffect(() => {
    setSelectedView(preferList ? 'agenda' :
      currentUser?.preferences?.calendarDefaults?.vormerkbuch ??
      systemConfig.calendarDefaults?.vormerkbuch ??
      'week'
    );
  }, [preferList, currentUser?.preferences?.calendarDefaults?.vormerkbuch, systemConfig.calendarDefaults?.vormerkbuch]);

  const fetchData = useCallback(async () => {
    try {
      const fetchedReservations = await database.getDocuments<BoatReservation>('boatReservations');
      setAllReservations(fetchedReservations);
    } catch (error) {
      console.error('Error fetching data:', error);
    }
  }, [database]);

  const handleToggleCancelled = useCallback(async () => {
    if (!currentUser || togglingCancelled) return;
    setTogglingCancelled(true);
    try {
      const newValue = !showCancelled;
      await database.updateDocument('users', currentUser.id, {
        preferences: {
          ...currentUser.preferences,
          showCancelledReservations: newValue,
        },
        updatedAt: new Date(),
      });
      await reloadCurrentUser();
    } catch (error) {
      console.error('Error saving calendar preference:', error);
    } finally {
      setTogglingCancelled(false);
    }
  }, [currentUser, database, showCancelled, togglingCancelled, reloadCurrentUser]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleSelectSlot = ({ start, end }: { start: Date; end: Date }) => {
    if (!currentUser) return;
    setSelectedSlot({ start, end });
    setIsReservationDialogOpen(true);
  };

  const handleSelectEvent = (reservation: BoatReservation) => {
    if (!currentUser) return;
    setSelectedReservation(reservation);
    setIsDetailsDialogOpen(true);
  };

  const handleCloseDialogs = () => {
    setIsDetailsDialogOpen(false);
    setIsReservationDialogOpen(false);
    setSelectedReservation(null);
    setSelectedSlot(null);
  };

  const handleReservationUpdate = () => {
    fetchData();
    handleCloseDialogs();
  };

  return (
    <Paper sx={{ p: { xs: 1, sm: 2 } }}>
      {!canReserve && (
        <Alert severity="warning" sx={{ mb: 2 }}>
          <AlertTitle sx={{ mb: 2 }}>Finale Reservierung aktuell nicht möglich</AlertTitle>
          Sie können trotzdem eine unverbindliche Vormerkung anlegen. Für eine finale Reservierung fehlen aktuell noch:
          <ul>
            {missingRequirements.map((req, index) => (
              <li key={index}>{req}</li>
            ))}
          </ul>
        </Alert>
      )}

      <Box sx={{ 
          mb: { xs: 1, sm: 2 }, 
          display: 'flex', 
          flexWrap: 'wrap', 
          gap: 0.5,
          mx: { xs: -1, sm: 0 },
          px: { xs: 1, sm: 0 },
          pb: 1,
          overflowX: 'auto',
          alignItems: 'center',
          '&::-webkit-scrollbar': {
            height: 6,
          },
          '&::-webkit-scrollbar-thumb': {
            backgroundColor: 'rgba(0,0,0,0.2)',
            borderRadius: 3,
          }
        }}>
        {boats.sort((a, b) => a.name.localeCompare(b.name)).map((boat) => (
          <Box
            key={boat.id}
            sx={{
              display: 'flex',
              alignItems: 'center',
              gap: 1,
              bgcolor: 'background.paper',
              border: 1,
              borderColor: 'divider',
              borderRadius: 1,
              px: 1,
              py: 0.5,
              fontSize: '0.875rem',
            }}
          >
            <Box
              sx={{
                width: 12,
                height: 12,
                borderRadius: '50%',
                backgroundColor: boat.color || '#ccc',
              }}
            />
            {boat.name}
          </Box>
        ))}
        <Box sx={{ ml: 'auto', display: 'flex', gap: 0.5, alignItems: 'center' }}>
          {isAdminOrSuperAdmin && (
            <Tooltip title={showCancelled ? 'Stornierte Reservierungen ausblenden' : 'Stornierte Reservierungen anzeigen'}>
              <Chip
                icon={<BlockIcon />}
                label="Stornierte"
                size="small"
                variant={showCancelled ? 'filled' : 'outlined'}
                color={showCancelled ? 'default' : 'default'}
                onClick={handleToggleCancelled}
                disabled={togglingCancelled}
                sx={{ opacity: showCancelled ? 1 : 0.6 }}
              />
            </Tooltip>
          )}
          {/* Neue Reservierung ohne Slot-Auswahl – auf Touch-Geräten sonst nur per langem Druck erreichbar. */}
          {currentUser && (
            <Button size="small" variant="contained" startIcon={<AddIcon />} onClick={() => handleSelectSlot(getDefaultNewSlot())}>
              {canReserve ? 'Reservieren' : 'Vormerken'}
            </Button>
          )}
        </Box>
      </Box>

      <Box
        sx={{
          position: 'relative',
        }}
      >
        <Calendar
          date={displayDate}
          localizer={localizer}
          events={reservations}
          longPressThreshold={100}
          scrollToTime={new Date(1970, 0, 1, 7, 0, 0)}
          eventPropGetter={(event, ...props) => {
            const boat = boats.find(b => b.id === event.boatId);
            const baseColor = event.status === 'draft'
              ? '#ed6c02'
              : event.status === 'pending'
                ? '#0288d1'
                : boat?.color || '#2e7d32';
            return {
              ...props,
              style: {
                backgroundColor: baseColor,
                borderColor: baseColor,
                color: getContrastColor(baseColor),
                opacity: event.status === 'cancelled' ? 0.5 : 1,
                borderStyle: event.visibility === 'public' ? 'dashed' : 'solid',
              },
            };
          }}
          components={{
            event: ({ event }) => (
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, overflow: 'hidden' }}>
                <Box component="span" sx={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                  {event.title}
                </Box>
                {event.visibility === 'public' && <Chip size="small" label="Öffentlich" color="secondary" sx={{ height: 18 }} />}
                {event.status === 'draft' && <Chip size="small" label="Vormerkung" color="warning" sx={{ height: 18 }} />}
              </Box>
            )
          }}
          startAccessor="startTime"
          endAccessor="endTime"
          style={calendarStyle}
          selectable={Boolean(currentUser)}
          onSelectSlot={handleSelectSlot}
          onSelectEvent={handleSelectEvent}
          view={selectedView}
          views={listView ? ['agenda', 'month', 'week', 'day'] : ['month', 'week', 'day']}
          onNavigate={(range) => {
            setDisplayDate(range);
          }}
          onView={(v) => setSelectedView(v as CalendarViewOption)}
          titleAccessor="title"
          messages={CALENDAR_MESSAGES}
        />
      </Box>

      {selectedReservation && (
        <ReservationDetailsDialog
          open={isDetailsDialogOpen}
          onClose={handleCloseDialogs}
          reservation={selectedReservation}
          onUpdate={handleReservationUpdate}
          onCopy={async (copies) => {
            await Promise.all(copies.map(async (copy) => {
              const copyWithSnapshot = {
                ...copy,
                userId: currentUser!.id,
                userName: currentUser!.displayName,
                eligibilitySnapshot: {
                  feesPaid: currentUser?.feesPaid ?? false,
                  skipHours: currentUser?.skipHours === true,
                  workHoursMet: canReserve,
                },
              };
              const newId = await database.addDocument('boatReservations', copyWithSnapshot);
              await syncPublicReservationFeed(database, { ...copyWithSnapshot, id: newId }, boats);
              await writeActivityLog(database, {
                type: 'reservation.created',
                entityId: newId,
                entityType: 'reservation',
                actorId: currentUser!.id,
                actorName: currentUser!.displayName,
                details: { title: copyWithSnapshot.title, status: copyWithSnapshot.status, seriesCopy: true },
              });
            }));
            await fetchData();
          }}
        />
      )}

      {selectedSlot && (
        <ReservationDialog
          open={isReservationDialogOpen}
          onClose={handleCloseDialogs}
          startTime={selectedSlot.start}
          endTime={selectedSlot.end}
          onUpdate={handleReservationUpdate}
        />
      )}
    </Paper>
  );
};
